{
  "cvars": {
    "ivs": [
      {
        "description": "Applicant gender indicator (1 = female, 0 = male). Primary independent variable to test whether being female changes the probability that a mortgage application is approved.",
        "columns": [
          "Female"
        ]
      }
    ],
    "dv": {
      "description": "Binary indicator for whether the mortgage application was approved (1 = approved / accepted, 0 = denied). Constructed from feature14 (preferred) or inverted feature11 when feature14 is missing.",
      "columns": [
        "Approved"
      ]
    },
    "controls": [
      {
        "description": "Indicator for whether the applicant is Black (1 = Black, 0 = otherwise). Controls for race-related differences in approval probability.",
        "is_moderator": false,
        "moderator_on": null,
        "columns": [
          "Black"
        ]
      },
      {
        "description": "Applicant self-employment status (1 = self-employed, 0 = otherwise). Controls for employment type.",
        "is_moderator": false,
        "moderator_on": null,
        "columns": [
          "SelfEmployed"
        ]
      },
      {
        "description": "Applicant marital status (1 = married, 0 = not married). Controls for household composition-related effects.",
        "is_moderator": false,
        "moderator_on": null,
        "columns": [
          "Married"
        ]
      },
      {
        "description": "Applicant mortgage credit score (numeric). Standardized version used in the model to aid interpretation and numerical stability.",
        "is_moderator": false,
        "moderator_on": null,
        "columns": [
          "z_MortgageScore"
        ]
      },
      {
        "description": "Applicant consumer credit score (numeric). Standardized version used in the model.",
        "is_moderator": false,
        "moderator_on": null,
        "columns": [
          "z_ConsumerScore"
        ]
      },
      {
        "description": "Indicator for a history of bad credit (1 = has bad credit history, 0 = otherwise). Controls for past credit issues.",
        "is_moderator": false,
        "moderator_on": null,
        "columns": [
          "BadCreditHistory"
        ]
      },
      {
        "description": "Housing expense as a ratio of total income (numeric). Standardized version used in the model to represent housing cost burden.",
        "is_moderator": false,
        "moderator_on": null,
        "columns": [
          "z_HousingExpenseRatio"
        ]
      },
      {
        "description": "Total debt payments to income ratio (numeric). Standardized version used in the model to control for debt burden.",
        "is_moderator": false,
        "moderator_on": null,
        "columns": [
          "z_DebtToIncomeRatio"
        ]
      },
      {
        "description": "Ratio of loan amount to appraised value of property (loan-to-value, numeric). Standardized version used in the model to control for LTV risk.",
        "is_moderator": false,
        "moderator_on": null,
        "columns": [
          "z_LoanToValueRatio"
        ]
      },
      {
        "description": "Indicator if private mortgage insurance application was denied (1 = denied PMI, 0 = otherwise). Controls for underwriting differences related to PMI.",
        "is_moderator": false,
        "moderator_on": null,
        "columns": [
          "PMI_Denied"
        ]
      }
    ]
  },
  "transform_code": "def transform(df: pd.DataFrame) -> pd.DataFrame:\n    df = df.copy()\n\n    # Create Approved variable:\n    # Prefer feature14 (1 if accepted). If missing, derive from feature11 (1 if denied) by inverting.\n    df['Approved'] = np.nan\n    if 'feature14' in df.columns:\n        df.loc[df['feature14'].notnull(), 'Approved'] = df.loc[df['feature14'].notnull(), 'feature14']\n    if 'feature11' in df.columns:\n        missing_approved = df['Approved'].isna() & df['feature11'].notna()\n        # feature11: 1 if denied -> Approved = 1 - feature11\n        df.loc[missing_approved, 'Approved'] = 1 - df.loc[missing_approved, 'feature11']\n\n    # Independent variable: Female (feature2: 1 if female, 0 if male)\n    df['Female'] = df['feature2']\n\n    # Controls: map columns to clear names\n    df['Black'] = df['feature3']\n    df['HousingExpenseRatio'] = df['feature4']\n    df['SelfEmployed'] = df['feature5']\n    df['Married'] = df['feature6']\n    df['MortgageScore'] = df['feature7']\n    df['ConsumerScore'] = df['feature8']\n    df['BadCreditHistory'] = df['feature9']\n    df['DebtToIncomeRatio'] = df['feature10']\n    df['LoanToValueRatio'] = df['feature12']\n    df['PMI_Denied'] = df['feature13']\n\n    # Required columns for the model\n    required_cols = [\n        'Approved', 'Female', 'Black', 'SelfEmployed', 'Married',\n        'MortgageScore', 'ConsumerScore', 'BadCreditHistory',\n        'HousingExpenseRatio', 'DebtToIncomeRatio', 'LoanToValueRatio', 'PMI_Denied'\n    ]\n\n    # Drop rows that are missing any required variable\n    df = df.dropna(subset=required_cols)\n\n    # Ensure binary columns are numeric 0/1\n    for bcol in ['Female', 'Black', 'SelfEmployed', 'Married', 'BadCreditHistory', 'PMI_Denied', 'Approved']:\n        df[bcol] = df[bcol].astype(float)\n\n    # Standardize continuous predictors (z-score). Use population std (ddof=0) for stability.\n    cont_cols = ['MortgageScore', 'ConsumerScore', 'HousingExpenseRatio', 'DebtToIncomeRatio', 'LoanToValueRatio']\n    for c in cont_cols:\n        mean = df[c].mean()\n        std = df[c].std(ddof=0)\n        if std == 0 or np.isnan(std):\n            df['z_' + c] = 0.0\n        else:\n            df['z_' + c] = (df[c] - mean) / std\n\n    # Final dataframe contains all model columns\n    final_cols = ['Approved', 'Female', 'Black', 'SelfEmployed', 'Married',\n                  'z_MortgageScore', 'z_ConsumerScore', 'BadCreditHistory',\n                  'z_HousingExpenseRatio', 'z_DebtToIncomeRatio', 'z_LoanToValueRatio', 'PMI_Denied']\n\n    # Return df with at least these columns available (but keep other columns as well)\n    return df\n",
  "m_code": "def model(df: pd.DataFrame) -> dict:\n    df = df.copy()\n\n    # Outcome and predictors\n    y = df['Approved'].astype(float)\n    X = df[[\n        'Female', 'Black', 'SelfEmployed', 'Married',\n        'BadCreditHistory', 'PMI_Denied',\n        'z_MortgageScore', 'z_ConsumerScore',\n        'z_HousingExpenseRatio', 'z_DebtToIncomeRatio', 'z_LoanToValueRatio'\n    ]]\n\n    # Add intercept\n    X = sm.add_constant(X, has_constant='add')\n\n    # Fit logistic regression (binary outcome) using statsmodels Logit\n    logit = sm.Logit(y, X)\n    # Use try/except to gracefully handle convergence issues\n    res = logit.fit(disp=False)\n\n    # Compute robust (heteroskedasticity-consistent) covariance estimates\n    res_robust = res.get_robustcov_results(cov_type='HC3')\n\n    # Compute average marginal effects for interpretable effect of Female (and others)\n    # If robust results support get_margeff, get marginal effects on the robust-fitted params.\n    try:\n        margeff = res_robust.get_margeff(at='overall', method='dydx')\n    except Exception:\n        # fall back to non-robust marginal effects\n        margeff = res.get_margeff(at='overall', method='dydx')\n\n    # Return key objects: robust model results and marginal effects summary\n    return {\n        'model_results_robust': res_robust,\n        'marginal_effects': margeff\n    }\n"
}
